import { test, expect } from '../../../fixtures';

test('TC-155: Regression: discount logic remains correct across mixed order values', async ({ api, loginAs }) => {
  // reset_state is automatic (harness beforeEach)
  await loginAs('standard_user');  // order creation requires an authenticated session
  // solved for subtotal exactly $99.99: 1x product 9 (Gaming Headset @ $99.99) -> subtotal $99.99 -- in the [99.00, 100.00) BR-1 discount boundary band (D4 surface)
  const res = await api.post('/api/orders', { data: { items: [{ product_id: 9, quantity: 1 }] } });
  expect(res.status()).toBe(201);
  const order = await res.json();
  expect(order.subtotal).toBe(99.99);
  expect(order.total).toBe(99.99);  // BR-1: no discount below $100.00 -> total equals subtotal
  expect(order.discount).toBe(0);
  // solved for subtotal exactly $100.00: 1x product 1 (Penny Sticker @ $0.01), 1x product 9 (Gaming Headset @ $99.99) -> subtotal $100.00
  const res2 = await api.post('/api/orders', { data: { items: [{ product_id: 1, quantity: 1 }, { product_id: 9, quantity: 1 }] } });
  expect(res2.status()).toBe(201);
  const order2 = await res2.json();
  expect(order2.subtotal).toBe(100);
  expect(order2.discount).toBeGreaterThan(0);  // BR-1: discount applies at subtotal >= $100.00
  // solved for subtotal exactly $250.00: 4x product 1 (Penny Sticker @ $0.01), 1x product 6 (Monitor Stand @ $34.99), 1x product 8 (Laptop Sleeve @ $10.00), 2x product 9 (Gaming Headset @ $99.99), 1x product 12 (Pocket Notebook @ $4.99) -> subtotal $250.00
  const res3 = await api.post('/api/orders', { data: { items: [{ product_id: 1, quantity: 4 }, { product_id: 6, quantity: 1 }, { product_id: 8, quantity: 1 }, { product_id: 9, quantity: 2 }, { product_id: 12, quantity: 1 }] } });
  expect(res3.status()).toBe(201);
  const order3 = await res3.json();
  expect(order3.subtotal).toBe(250);
  expect(order3.discount).toBeGreaterThan(0);  // BR-1: discount applies at subtotal >= $100.00
});
